#ifdef NDEBUG
#error "Assertions must remain enabled."
#endif
#include <cassert>
#include <iostream>
struct Intent { int move; int aim; bool fire; };
struct State { int x; int aim; int shots; };
bool apply(State& s,const Intent& i){
    if(i.move < -1 || i.move > 1 || i.aim < -2 || i.aim > 2)return false;
    const int x=s.x+i.move;
    if(x < -5 || x > 5)return false; // 이번 계약은 명령 전체 거부
    s.x=x;s.aim=i.aim;if(i.fire)++s.shots;return true;
}
int main(){
    State a{0,0,0};assert(apply(a,Intent{1,-2,true}));
    assert(a.x==1 && a.aim==-2 && a.shots==1);
    assert(!apply(a,Intent{2,0,true}));assert(a.shots==1 && a.x==1);
    State edge{5,1,0};assert(!apply(edge,Intent{1,-1,true}));
    assert(edge.x==5 && edge.aim==1 && edge.shots==0);
    assert(apply(edge,Intent{0,-1,true}));assert(edge.shots==1);
    std::cout<<"intent separation tests passed\n";
}
